INSERT OR IGNORE INTO manual_sections
  (manual_key, section_key, title, body, sort_order, version, updated_by, updated_at)
VALUES
  ('owner','false-escalation-guard','False escalation guard နှင့် clarification flow','User က 1, 2, 123 လို numbers only, punctuation only, single emoji/symbol, URL-only, username/phone-only, repeated garbage, acknowledgement-only သို့မဟုတ် context မလုံလောက်သော input ပို့လာပါက Staff Inbox case မဖန်တီးမီ Input Quality Gate က စစ်ပါတယ်။ Obvious low-information input ဆို AI ကို မခေါ်ဘဲ localized clarification message ပြန်ပြီး /faq ကိုညွှန်ပြပါတယ်။ ဒီလို filtered input ကို /cases ထဲမထည့်ပါ။\n\nShort message အားလုံးကို မပိတ်ပါ။ fees?, tuition, admission, CDM, accreditation လို short-but-meaningful School of Nursing topic queries ကို normal FAQ/AI flow ဆက်လုပ်ခွင့်ပြုပါတယ်။ Human-controlled conversation နဲ့ active admin/setup session တွေကို quality gate မဖြတ်ပါ။\n\nAI policy မှာ clarify decision ပါရှိပါတယ်။ Meaningful ဖြစ်ပေမယ့် incomplete/ambiguous ဖြစ်ပြီး staff က action/review လုပ်ဖို့ context မလုံလောက်သေးရင် AI က clarification ကိုပဲ ပြန်တောင်းရမယ်၊ handoff မလုပ်ရပါ။ Human handoff က sufficiently specific School of Nursing question ဖြစ်ပြီး approved knowledge မလုံလောက်ခြင်း၊ case-specific decision/action လိုခြင်း စတဲ့ real staff-review need ရှိမှသာလုပ်ရပါတယ်။',95,1,0,CURRENT_TIMESTAMP),
  ('admin','false-escalation-guard','False escalation နှင့် clarification','Numbers-only, punctuation-only, emoji/symbol-only, URL/username/phone-only, repeated garbage, acknowledgement-only သို့မဟုတ် obvious incomplete input ကို system က false escalation အဖြစ် filter လုပ်ပါတယ်။ အဲ့ဒီ input တွေကို AI မခေါ်ဘဲ user ကို ပိုပြည့်စုံသောမေးခွန်းရေးရန် localized message ပြန်ပြီး /faq ကိုညွှန်ပြပါတယ်။ Case အသစ်မဖန်တီးပါ။\n\nfees?, tuition, admission, CDM လို short-but-meaningful topic queries ကိုတော့ မပိတ်ပါ။ AI က meaningful but unclear input အတွက် clarify ပြန်နိုင်ပြီး context ပြည့်စုံသော real unanswered School of Nursing question မှသာ human escalation ဖြစ်သင့်ပါတယ်။ Human takeover conversation သို့မဟုတ် active admin/setup wizard text ကို false-escalation filter မသုံးပါ။',95,1,0,CURRENT_TIMESTAMP);
